export type TranslationKey = keyof typeof catalog
export type Locale = 'ru' | 'en' | 'kk'
const order: Readonly<Record<Locale, number>> = {ru:0,en:1,kk:2}

export function normalizeLocale(value: string | null | undefined): Locale {
  const text = (value || '').toLowerCase()
  if (text === 'kk' || text === 'kz' || text.startsWith('kk-') || text.startsWith('kz-')) return 'kk'
  if (text === 'en' || text.startsWith('en-')) return 'en'
  return 'ru'
}

export function translate(key: TranslationKey | string, locale: Locale, params: Record<string, string | number> = {}): string {
  const row = catalog[key as TranslationKey] as readonly string[] | undefined
  const source = row ? row[order[locale]] : key
  return source.replace(/\{(\w+)\}/g, (_, name: string) =>
    Object.prototype.hasOwnProperty.call(params, name) ? String(params[name]) : '{' + name + '}')
}

export const LOCALE_NUMBER_FORMAT: Readonly<Record<Locale, string>> = {
  ru: 'ru-RU', en: 'en-US', kk: 'kk-KZ',
}
